/// The rules `owner_select` scans, in Core order (`helper_group`).
fn helper_group(kind: u128) -> &'static [RuleIdC] {
    use RuleIdC::*;
    match kind {
        H_SCALAR => &[
            BHelperScalarConstruct,
            BHelperScalarArithmetic,
            BHelperScalarTag,
            BHelperScalarFailure,
            BHelperScalarExit,
        ],
        H_ENVGET => &[
            BHelperEnvGetExit,
            BHelperEnvGetFailure,
            BHelperEnvGetCell,
            BHelperEnvGetEmpty,
        ],
        H_ENVPUT => &[BHelperEnvPutInsert, BHelperEnvPutExit],
        H_FIND => &[
            BHelperFindExit,
            BHelperFindFailure,
            BHelperFindRow,
            BHelperFindEmpty,
        ],
        H_BIND => &[
            BHelperBindExit,
            BHelperBindFailure,
            BHelperBindPair,
            BHelperBindEmpty,
            BHelperBindArity,
            BHelperBindType,
            BHelperBindDuplicate,
            BHelperBindInsert,
            BHelperBindPropagate,
        ],
        H_APPEND => &[
            BHelperAppendCopy,
            BHelperAppendCell,
            BHelperAppendEmpty,
            BHelperAppendTail,
            BHelperAppendExit,
        ],
        H_VALIDATE => &[
            BBookkeepingTaskRelease,
            BHelperValidateFailure,
            BHelperValidateExit,
            BHelperValidateEmpty,
            BHelperValidateInvalid,
            BHelperValidateOccurrence,
            BHelperValidateField,
        ],
        H_EQUAL => &[
            BBookkeepingTaskRelease,
            BHelperEqualExit,
            BHelperEqualEmpty,
            BHelperEqualDifferent,
            BHelperEqualPair,
            BHelperEqualField,
        ],
        H_MATCH => &[
            BHelperMatchExit,
            BHelperMatchFailure,
            BHelperMatchArm,
            BHelperMatchOccurrence,
            BHelperMatchDistinct,
            BHelperMatchField,
            BHelperMatchBinding,
            BHelperMatchSelected,
            BHelperMatchNext,
        ],
        _ => &[],
    }
}

