            return Err(C6ProgramContextCanonicalError::LengthMismatch {
                expected: PROGRAM_HEADER_LANES,
                actual: pre_prog.len(),
            });
        }
        let mut em = Emitter::new(&self.scope, self.next_temp);
        let gate = gate.clone();
        em.cbool(gate.clone());
        em.cbits(index.clone(), LANE_BITS);
