            count = em.sel(count_phase, lane.clone(), count);
            let row_phase = em.eqv(regs.phase.clone(), row_ph);
            let index_eq = em.teq(row_index.clone(), index.clone());
            let selected = em.and(row_phase.clone(), index_eq);
