    let mut fns: Vec<usize> = Vec::new();
    let mut names: Vec<usize> = Vec::new();
    let mut arms: Vec<usize> = Vec::new();
    let mut refs: Vec<RefC> = Vec::new();
    if let Write::Set(c) = &w.control {
        control_refs(c, &mut refs);
        match c {
            ControlC::Eval { expr } => exprs.push(*expr),
            ControlC::ScheduleNext { frame, next, .. } => {
                check_written_frame_adt_ids(view, frame)?;
                frame_code_ids(frame, &mut exprs, &mut names);
                exprs.push(*next);
