                names.push(*binder)
            }
            HelperControlC::Find {
                function_name,
                found,
                ..
            } => {
                names.push(*function_name);
                fns.extend(*found);
            }
            HelperControlC::Bind { function, .. } => fns.push(*function),
            HelperControlC::Match {
                arm,
                pat_tag,
                x,
                y,
                phase,
                ..
            } => {
                arms.push(*arm);
                if *phase != MatchPhase::Arm {
                    match pat_tag {
                        PatternTag::PVar | PatternTag::PLeaf => names.push(*x),
                        PatternTag::PCons | PatternTag::PBranch => {
                            names.push(*x);
                            names.push(*y);
            0
        },
        alloc_data_fields: w.alloc_data.map_or(0, |a| a.field_len() as i64)
            + if w.alloc_data_field.is_some() { 1 } else { 0 },
        alloc_environment_cells: if w.alloc_env.is_some() { 1 } else { 0 },
        depth: match w.frame {
            Some(FrameWrite::Push(_)) => 1,
            Some(FrameWrite::Pop) => -1,
            _ => 0,
        },
        task_live: match w.task_op {
            TaskOp::Push(_) => 1,
            TaskOp::Pop => -1,
            TaskOp::None => 0,
        },
        active_value_slots: if w.alloc_value_slot.is_some() { 1 } else { 0 },
    }
