fn validate_slices_in_control(
    pre: &PreImage,
    w: &PlannedWrites,
    c: &ControlC,
) -> Result<(), HostViolation> {
    match c {
        ControlC::Invoke { args, .. } | ControlC::Enter { args, .. } => {
            check_slice(*args, pre.img.active.value_slots)
        }
        ControlC::Materialize { fields, .. } => check_slice(*fields, post_slot_len(pre, w)?),
        ControlC::Cases { arms, .. } => check_slice(*arms, pure_view(pre)?.arms.len()),
        ControlC::CaseResult { rest, .. } => check_slice(*rest, pure_view(pre)?.arms.len()),
        ControlC::ScheduleNext { frame, .. } => validate_slices_in_frame(pre, w, frame),
        _ => Ok(()),
    }
}
fn validate_slices_in_frame(
    pre: &PreImage,
    w: &PlannedWrites,
    f: &FrameRowC,
) -> Result<(), HostViolation> {
    match f {
        FrameRowC::MatchF { arms, .. } => check_slice(*arms, pure_view(pre)?.arms.len()),
        FrameRowC::ArgsF {
            completed, rest, ..
        } => {
            check_slice(*completed, pre.img.active.value_slots)?;
            check_slice(*rest, pure_view(pre)?.children.len())
        }
        FrameRowC::ConstructorFieldsF {
            completed, rest, ..
        } => {
            check_slice(*completed, post_slot_len(pre, w)?)?;
            check_slice(*rest, pure_view(pre)?.children.len())
        }
        _ => Ok(()),
    }
}
fn validate_slices_in_helper(pre: &PreImage, h: &HelperControlC) -> Result<(), HostViolation> {
    match h {
        HelperControlC::Bind { params, args, .. } => {
            check_slice(*params, pure_view(pre)?.parameters.len())?;
            check_slice(*args, pre.img.active.value_slots)
        }
        HelperControlC::Append { src, .. } | HelperControlC::Build { src, .. } => {
            check_slice(*src, pre.img.active.value_slots)
        }
        HelperControlC::Plan { path, .. } => check_slice(*path, pure_view(pre)?.field_paths.len()),
        _ => Ok(()),
    }
}
