pub fn owner_physical_check(pre: &PreImage, v: &ValidatedPlan) -> Result<(), HostViolation> {
    if v.cap_first.is_some() {
        return Ok(());
    } // P6 refusal: no physical check applies.
    let b = &pre.admitted.body.bounds;
    let w = &v.writes;
    let bad = ((w.alloc_data.is_some() || w.alloc_constructor.is_some())
        && pre.img.active.data >= b.data_nodes)
        || (v.delta.alloc_data_fields > 0
            && pre
                .img
                .active
                .data_fields
                .checked_add(v.delta.alloc_data_fields as usize)
                .map_or(true, |n| n > b.data_field_slots))
        || (w.alloc_env.is_some() && pre.img.active.env >= b.environment_cells)
        || (w.alloc_value_slot.is_some()
            && pre.img.active.value_slots >= pre.admitted.body.layout.capacities.value_slots)
        || (matches!(w.frame, Some(FrameWrite::Push(_))) && pre.depth() >= b.frames)
        || (matches!(w.task_op, TaskOp::Push(_)) && pre.task_live() >= b.helper_tasks);
    if bad {
        Err(hv(
            HostViolationKind::PhysicalCapacityExceeded,
            None,
            Some(v.rule()),
            "physical capacity",
        ))
    } else {
        Ok(())
    }
}

