// result_plan = helperPlan(site(pre), pre) for a staged pre.result (adopted helperKind branch 3), computed purely before any write.
fn snap(pre: &PreImage) -> Result<Snap, HostViolation> {
    let img = pre.img;
    let result_plan = if img.result.is_some() {
        owner_helper_plan(owner_site(pre)?, pre)
    } else {
        None
    };
    let occurrence = pre.occurrence(&img.control_origin)?;
    let source_occurrence = LocatorC::Occurrence {
        owner_is_function: occurrence.owner_is_function,
        function: occurrence.function,
        ast_path: pre.occurrence_path(&occurrence.path)?.to_vec(),
    };
    Ok(Snap {
        consumed: img.consumed_work,
        cursor: img.reference_cursor,
        origin: img.control_origin,
        helper: img.helper,
        result: img.result,
        result_plan,
        depth: img.frames.len(),
        tasks: img.tasks.len(),
        source_occurrence,
    })
}
