pub const PROGRAM_SECTION_TAG: u128 = 0x5052_4F47;
pub const PROGRAM_HEADER_LANES: usize = 4;

fn check_count(section: &'static str, count: usize, limit: usize) -> C6Result<()> {
    if count > limit {
        return Err(C6PhysError::CapacityExceeded {
            section,
            needed: count,
            limit,
        });
    }
    Ok(())
}

fn binary_tag(op: BinaryOp) -> u128 {
    match op {
        BinaryOp::Add => 0,
        BinaryOp::Sub => 1,
        BinaryOp::Mul => 2,
        BinaryOp::Eq => 3,
        BinaryOp::Lt => 4,
        BinaryOp::Cons => 5,
        BinaryOp::Branch => 6,
    }
}

fn binary_from_tag(tag: u128) -> C6Result<BinaryOp> {
    Ok(match tag {
        0 => BinaryOp::Add,
        1 => BinaryOp::Sub,
        2 => BinaryOp::Mul,
        3 => BinaryOp::Eq,
        4 => BinaryOp::Lt,
        5 => BinaryOp::Cons,
        6 => BinaryOp::Branch,
        _ => {
            return Err(C6PhysError::BadTag {
                section: "program.binary_op",
                tag,
            });
        }
    })
}

fn unary_tag(op: UnaryOp) -> u128 {
    match op {
        UnaryOp::Leaf => 0,
        UnaryOp::Not => 1,
    }
}

fn unary_from_tag(tag: u128) -> C6Result<UnaryOp> {
    Ok(match tag {
        0 => UnaryOp::Leaf,
        1 => UnaryOp::Not,
        _ => {
            return Err(C6PhysError::BadTag {
                section: "program.unary_op",
                tag,
            });
        }
    })
}

#[derive(Clone, Copy)]
enum TextBudget {
    Names,
    Template,
}

impl TextBudget {
    fn section(self) -> &'static str {
        match self {
            TextBudget::Names => "program.name_bytes",
            TextBudget::Template => "program.template_bytes",
        }
    }
    fn limit(self, caps: &C6PhysCaps) -> usize {
        match self {
            TextBudget::Names => caps.max_name_bytes,
            TextBudget::Template => caps.max_template_bytes,
        }
    }
}

